"""Listening Batch 3: Material für Probetest 3 und 4 (44 Choose, 12 Conversations, 12 Announcements, 12 Talks)."""
from contentlib import MC, append
mc = MC(start=1, seed=303)

C = []
def ch(id, level, voice, skill, prompt, correct, wrong, why):
    m = mc("", correct, wrong, why); C.append({"id": id, "level": level, "voice": voice, "skill": skill, "prompt": prompt, "options": m["options"], "answer": m["answer"], "why": why})
